widgets.example:
TopAppBar(
  title: AppText.bodyLgSemiBold(text: 'Dashboard', textColor: AppColors.colorBlack),
  prefix: AppIcon(svgIconPath: AppAssets.back, width: 24, height: 24, onTap: () {}),
  suffix: Icon(Icons.settings_outlined, color: AppColors.colorGray1400),
)

// Suffix with icon button:
TopAppBar(
  title: AppText.bodyLgSemiBold(text: 'Profile'),
  suffix: GestureDetector(
    onTap: () {},
    child: const Icon(Icons.notifications_outlined),
  ),
)

// Use AppIcon ONLY with the 7 kit SVG constants:
AppIcon(
  svgIconPath: AppAssets.alertCircle,
  width: 24,
  height: 24,
  colorFilter: ColorFilter.mode(AppColors.colorRed1200, BlendMode.srcIn),
)

// Tappable:
AppIcon(svgIconPath: AppAssets.close, width: 20, height: 20, onTap: () {})

// For ANY other icon (home, settings, search, bell, …) use Flutter Material:
// Icon(Icons.home_outlined, color: AppColors.colorBlue1200, size: 24)

showModalBottomSheet(
  context: context,
  builder: (context) => AppBottomSheet(
    body: Column(children: [/* content */]),
  ),
)

const AppLoadingView(
  loadingText: 'Loading...',
)

showDialog(
  context: context,
  builder: (context) => AppModalDialog(
    modalHeaderTitle: 'Confirm Action',
    bodyWidget: AppText.bodyMd(text: 'Are you sure?', textColor: TextColors.colorText),
    footerWidget: Row(
      children: [
        Expanded(child: AppOutlinedButton.medium(btnText: 'Cancel', onTap: () => Navigator.pop(context), width: double.infinity)),
        const SizedBox(width: 12),
        Expanded(child: AppFilledButton.medium(btnText: 'Confirm', onTap: () {}, width: double.infinity)),
      ],
    ),
  ),
)

// Shows brand SVG logo:
const AppLogo(width: 120, height: 40)

// Custom asset:
AppLogo(appIconPath: AppAssets.appLogoSvg, width: 80)
